def state_machine():
    state = "开始"
    while True:
        received = yield state
        if received == "go":
            state = "运行"
        elif received == "stop":
            break


sm = state_machine()
print(next(sm))
print(sm.send("go"))

try:
    sm.send("stop")
except StopIteration:
    print("结束")
